import React, { useState, useRef } from 'react';
import { useDropzone } from 'react-dropzone';
import { Upload, FileText, CheckCircle2, ShieldCheck, GitBranch, Cpu, RefreshCw, ArrowRight, Zap, Terminal } from 'lucide-react';
import { useAnalyze } from '../hooks/useAnalyze';
import LoadingScreen from '../components/LoadingScreen';
import BackgroundEffects from '../components/BackgroundEffects';
import GiganticHolographicEarth from '../components/GiganticHolographicEarth';
import CommandDock from '../components/CommandDock';
import SharedProfilesExplorer from '../components/SharedProfilesExplorer';
import { useNavigate } from 'react-router-dom';

const Home = () => {
  const [file, setFile] = useState(null);
  const [jobDescription, setJobDescription] = useState('');
  const [showExplorer, setShowExplorer] = useState(false);

  const commandCenterRef = useRef(null);
  const { analyze, loading, progress, currentStep } = useAnalyze();
  const navigate = useNavigate();

  const onDrop = (acceptedFiles) => {
    if (acceptedFiles.length > 0) {
      setFile(acceptedFiles[0]);
    }
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'application/pdf': ['.pdf'],
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx']
    },
    maxFiles: 1
  });

  const scrollToCommandCenter = () => {
    if (commandCenterRef.current) {
      commandCenterRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleAnalyze = () => {
    console.log('[DEBUG Home.js] "Analyze Resume & Verify Profile" button clicked!');
    if (!file) {
      console.warn('[DEBUG Home.js] Validation failed: No file uploaded.');
      alert('Please upload a resume (PDF or DOCX)');
      return;
    }

    if (!jobDescription.trim()) {
      console.warn('[DEBUG Home.js] Validation failed: Job description empty.');
      alert('Please enter a job description');
      return;
    }

    console.log('[DEBUG Home.js] Validation passed. Calling analyze() hook...');
    analyze(file, jobDescription);
  };

  const handleSelectMockProfile = (mockAnalysis) => {
    sessionStorage.setItem('analysisResult', JSON.stringify(mockAnalysis));
    navigate('/results');
  };

  const statusPanels = [
    { name: 'Resume Engine', status: 'ONLINE', icon: FileText, signal: 98, color: 'text-scifi-100' },
    { name: 'GitHub Scanner', status: 'SYNCING', icon: GitBranch, signal: 94, color: 'text-scifi-200' },
    { name: 'Trust Engine', status: 'VERIFYING', icon: ShieldCheck, signal: 99, color: 'text-scifi-100' },
    { name: 'Skill Matching', status: 'PROCESSING', icon: RefreshCw, signal: 96, color: 'text-scifi-200' },
    { name: 'OCR', status: 'READY', icon: Terminal, signal: 100, color: 'text-scifi-100' },
    { name: 'ATS', status: 'ACTIVE', icon: CheckCircle2, signal: 95, color: 'text-scifi-200' },
  ];

  if (loading) {
    return (
      <LoadingScreen
        progress={progress}
        currentStep={currentStep}
      />
    );
  }

  return (
    <div className="min-h-screen bg-scifi-900 text-scifi-100 relative overflow-hidden pb-24 font-sans">
      {/* Deep Purple Infinite Space Environment */}
      <BackgroundEffects />

      {/* MAIN HERO: GIGANTIC 3D HOLOGRAPHIC INTELLIGENCE CORE */}
      <div className="max-w-7xl mx-auto px-4 pt-6 sm:pt-10 relative z-10">

        <div className="grid lg:grid-cols-12 gap-6 items-center min-h-[80vh]">

          {/* Left Column: Minimal Headline */}
          <div className="lg:col-span-4 text-left space-y-4">
            <h1 className="text-4xl sm:text-6xl font-heading font-extrabold tracking-tight leading-tight text-scifi-100">
              One Identity. <br />
              <span className="bg-clip-text text-transparent bg-gradient-to-r from-scifi-100 via-scifi-200 to-scifi-400 glow-text-purple">
                Multiple Verifications.
              </span>
            </h1>

            <p className="text-sm sm:text-base text-scifi-200 font-sans leading-relaxed">
              Autonomous verification platform monitoring developer resume claims, code evidence, and trust ratings in real time.
            </p>

            <div className="pt-2">
              <button
                onClick={scrollToCommandCenter}
                className="px-6 py-3.5 rounded-xl bg-scifi-600/30 hover:bg-scifi-600/50 text-scifi-100 font-mono text-xs font-semibold border border-scifi-600/50 shadow-purple-glow transition-all inline-flex items-center space-x-2"
              >
                <span>Upload Resume</span>
                <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* Center Column: GIGANTIC 3D HOLOGRAPHIC EARTH CORE */}
          <div className="lg:col-span-5 flex items-center justify-center">
            <GiganticHolographicEarth />
          </div>

          {/* Right Column: Live Glass Status Panels */}
          <div className="lg:col-span-3 space-y-2.5">
            <div className="text-xs font-mono text-scifi-200 uppercase tracking-widest mb-3 text-left">
              Engine Status
            </div>

            {statusPanels.map((panel, idx) => {
              const Icon = panel.icon;
              return (
                <div
                  key={idx}
                  className="glass-card p-3 rounded-xl border border-scifi-600/25 flex items-center justify-between transition-all hover:border-scifi-600/50 shadow-sm"
                >
                  <div className="flex items-center space-x-2.5">
                    <Icon className={`w-4 h-4 ${panel.color}`} />
                    <span className="text-xs font-mono font-medium text-scifi-100">{panel.name}</span>
                  </div>

                  <div className="flex items-center space-x-2">
                    {/* Signal Strength Dots */}
                    <div className="flex items-center space-x-0.5">
                      <span className="w-1 h-2 bg-scifi-200 rounded-xs" />
                      <span className="w-1 h-2.5 bg-scifi-200 rounded-xs" />
                      <span className="w-1 h-3 bg-scifi-100 rounded-xs" />
                    </div>

                    {/* Status Pill */}
                    <div className="flex items-center space-x-1 pl-1">
                      <span className="h-1.5 w-1.5 rounded-full bg-scifi-100 animate-pulse" />
                      <span className="text-[10px] font-mono font-bold tracking-wider text-scifi-200">
                        {panel.status}
                      </span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

        </div>
      </div>

      {/* INPUT COMMAND CENTER DROPZONE */}
      <div ref={commandCenterRef} className="max-w-6xl mx-auto px-4 pt-16 relative z-10">

        <div className="text-center mb-8">
          <h2 className="text-2xl sm:text-4xl font-heading font-extrabold text-scifi-100 tracking-tight">
            Developer Verification Core
          </h2>
          <p className="text-scifi-200 text-xs font-mono mt-1">
            Upload resume file or select from team shared mock dataset
          </p>
        </div>

        <div className="grid md:grid-cols-2 gap-6 mb-8">

          {/* Resume Upload Dropzone */}
          <div className="glass-card p-6 rounded-3xl border border-scifi-600/30 shadow-2xl relative overflow-hidden group">
            <div className="absolute inset-0 bg-scanline-purple pointer-events-none opacity-40" />

            <h3 className="text-lg font-heading font-bold mb-4 flex items-center text-scifi-100">
              <Upload className="w-5 h-5 mr-2 text-scifi-200" />
              1. Resume File Upload
            </h3>

            <div
              {...getRootProps()}
              className={`relative border-2 border-dashed rounded-2xl p-6 text-center cursor-pointer transition-all duration-300 ${
                isDragActive
                  ? 'border-scifi-400 bg-scifi-600/20 shadow-purple-glow scale-[1.01]'
                  : 'border-scifi-600/30 bg-scifi-950/60 hover:border-scifi-600/60'
              }`}
            >
              <input {...getInputProps()} />

              {file ? (
                <div className="flex flex-col items-center justify-center space-y-2 py-2">
                  <div className="p-3 rounded-xl bg-scifi-600/20 border border-scifi-600/50 text-scifi-100">
                    <FileText className="w-8 h-8" />
                  </div>
                  <p className="font-heading font-bold text-scifi-100 text-sm">{file.name}</p>
                  <span className="px-3 py-0.5 rounded-full text-[10px] font-mono bg-scifi-600/30 text-scifi-100 border border-scifi-600/50">
                    ✓ Validated
                  </span>
                </div>
              ) : (
                <div className="py-4 space-y-3">
                  <Upload className="w-8 h-8 mx-auto text-scifi-200" />
                  <p className="text-scifi-100 font-medium text-xs">
                    {isDragActive ? 'Drop resume here...' : 'Drag & drop resume (PDF / DOCX)'}
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* Job Description Text Area */}
          <div className="glass-card p-6 rounded-3xl border border-scifi-600/30 shadow-2xl">
            <h3 className="text-lg font-heading font-bold mb-4 flex items-center text-scifi-100">
              <FileText className="w-5 h-5 mr-2 text-scifi-200" />
              2. Target Job Description
            </h3>

            <textarea
              value={jobDescription}
              onChange={(e) => setJobDescription(e.target.value)}
              placeholder="Paste target job description requirements here..."
              className="w-full h-36 glass-input rounded-2xl p-4 text-scifi-100 placeholder-scifi-200/50 focus:outline-none resize-none font-sans text-xs leading-relaxed"
            />
          </div>

        </div>

        {/* Big Glow Action Button */}
        <div className="text-center">
          <button
            onClick={handleAnalyze}
            disabled={!file || !jobDescription.trim()}
            className="group relative inline-flex items-center justify-center px-10 py-4.5 rounded-2xl font-heading font-extrabold text-base text-scifi-100 bg-gradient-to-r from-scifi-700 via-scifi-600 to-scifi-800 disabled:opacity-40 disabled:cursor-not-allowed transition-all duration-300 hover:scale-[1.03] shadow-purple-glow overflow-hidden"
          >
            <Zap className="w-5 h-5 mr-2 text-scifi-200 group-hover:animate-bounce" />
            <span>Analyze Resume & Verify Profile</span>
            <ArrowRight className="w-4 h-4 ml-2 group-hover:translate-x-1 transition-transform" />
          </button>

          {/* Dataset Explorer Toggle */}
          <div className="mt-4">
            <button
              onClick={() => setShowExplorer(!showExplorer)}
              className="inline-flex items-center space-x-2 text-xs font-mono text-scifi-200 hover:text-scifi-100 underline underline-offset-4 transition-colors"
            >
              <Cpu className="w-4 h-4" />
              <span>{showExplorer ? 'Hide Shared Mock Dataset Explorer' : 'Explore 20 Shared Developer Mock Profiles & SkillSwap Pairs'}</span>
            </button>
          </div>
        </div>

        {/* Shared Mock Profiles Explorer */}
        {showExplorer && (
          <SharedProfilesExplorer onSelectProfile={handleSelectMockProfile} />
        )}

      </div>

      {/* Floating Bottom Command Dock */}
      <CommandDock onSelectModule={(m) => console.log('Selected module:', m)} />
    </div>
  );
};

export default Home;
